7	/**
8	 * Append-only JSONL of every event a session produced, one file per session
9	 * under `.agent/runs/<session id>/events.jsonl`. The transcript view is
10	 * rebuilt from it after a reload, and later phases read it for observability.
11	 *
12	 * Writes are chained so entries land in emission order even when the caller
13	 * does not await.
14	 */
15	export class RunLog {
16	  private chain: Promise<void> = Promise.resolve()
17	
18	  /** The session's run directory; what belongs to this run and not to the workspace lives here. */
19	  constructor(readonly dir: string) {}
20	
21	  static forSession(workspaceRoot: string, sessionId: string): RunLog {
22	    return new RunLog(join(workspaceRoot, '.agent', 'runs', sessionId))
23	  }
24	
25	  get path(): string {
26	    return join(this.dir, 'events.jsonl')
27	  }
28	
29	  /** Resolves once every append queued so far has landed, so a read sees them. */
30	  settled(): Promise<void> {
31	    return this.chain
32	  }
33	
34	  append(event: SessionEvent): Promise<void> {
35	    const entry: RunLogEntry = { at: new Date().toISOString(), event }
36	    this.chain = this.chain.then(async () => {
37	      await mkdir(this.dir, { recursive: true })
38	      await appendFile(this.path, JSON.stringify(entry) + '\n', 'utf8')
39	    })
40	    return this.chain
41	  }
42	
43	  async read(): Promise<RunLogEntry[]> {
44	    let text: string
45	    try {
46	      text = await readFile(this.path, 'utf8')
47	    } catch (error) {
48	      if (isMissingFile(error)) return []
49	      throw error
50	    }
51	    return text
52	      .split('\n')
53	      .filter((line) => line.length > 0)
54	      .map((line) => JSON.parse(line) as RunLogEntry)
55	  }
56	}
57	
58	function isMissingFile(error: unknown): boolean {
59	  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT'
60	}
