const files = (await glob({ pattern: '.agent/runs/*/events.jsonl' })).split('\n').filter(Boolean)
const rows = []
for (const f of files) {
  let text
  try { text = await read(f) } catch (e) { rows.push({ f, err: String(e).slice(0,80) }); continue }
  const lines = text.split('\n').filter(Boolean)
  let first, last, users = 0, firstUser
  for (const l of lines) {
    let e
    try { e = JSON.parse(l) } catch { continue }
    first ??= e.at; last = e.at
    if (e.event?.type === 'user_message') { users++; firstUser ??= (e.event.text || '').slice(0, 50) }
  }
  rows.push({ id: f.split(/[\\/]/).slice(-2)[0].slice(0, 8), kb: Math.round(text.length / 1024), lines: lines.length, users, first: (first||'').slice(0,16), last: (last||'').slice(0,16), prompt: firstUser })
}
rows.sort((a, b) => String(a.first).localeCompare(String(b.first)))
return `${files.length} run dirs with a log\n` + rows.map(r => JSON.stringify(r)).join('\n')

